function saveCookie(){
  var m = source.getLoginInfoMap();
  var ck = String((m && m.get('Cookie')) || java.get('Cookie') || '').trim();
  if (ck.length < 10) { java.longToast('请先粘贴浏览器里的 Cookie'); return; }
  source.putLoginHeader(JSON.stringify({'Cookie': ck}));
  java.longToast('Cookie 已保存，可直接阅读');
}
function login(){ saveCookie(); }
